 if(type==='logistic'){const n=20+Math.floor(780*Math.min(1,(t%4)/3.2));c.fillStyle=LAB.orange;let x=.317;const r=3.82;for(let i=0;i<n;i++){x=r*x*(1-x);if(i>20)c.fillRect((i-20)/780*w,h*(1-x),1.2,1.2)}c.beginPath();c.arc((n-21)/780*w,h*(1-x),3.5,0,7);c.fill()}
 if(type==='montecarlo'){let seed=17,inside=0;const rand=()=>((seed=(seed*16807)%2147483647)-1)/2147483646,n=Math.max(1,Math.floor(240*Math.min(1,(t%4)/3.2)));c.strokeStyle='#526074';c.strokeRect(w*.15,h*.08,h*.75,h*.75);c.beginPath();c.arc(w*.15+h*.375,h*.455,h*.375,0,7);c.stroke();for(let i=0;i<n;i++){const x=rand(),y=rand(),inn=(x-.5)**2+(y-.5)**2<=.25;inside+=inn;c.fillStyle=inn?LAB.purple:'#3b4658';c.fillRect(w*.15+x*h*.75,h*.08+y*h*.75,2,2)}c.fillStyle='#d7e6f7';c.font='11px "JetBrains Mono",monospace';c.fillText(`π ≈ ${(4*inside/n).toFixed(2)}`,12,h-12)}
 if(type==='earth'){const r=Math.min(w,h)*.34,cx=w/2,cy=h/2,a=t/4*2*Math.PI;c.strokeStyle='#39d9c2';c.beginPath();c.arc(cx,cy,r,0,7);c.stroke();c.globalAlpha=.35;for(let k=-2;k<=2;k++){c.beginPath();c.ellipse(cx,cy,Math.abs(r*Math.cos(k*.24+a/2)),r,0,0,7);c.stroke();c.beginPath();c.ellipse(cx,cy,r,r*Math.cos(k*.24),0,0,7);c.stroke()}c.globalAlpha=1;const ux=Math.cos(a)*r*.82,uy=Math.sin(a)*r*.52;c.strokeStyle=LAB.yellow;c.beginPath();c.moveTo(cx-ux,cy-uy);c.lineTo(cx+ux,cy+uy);c.stroke();for(const [x,y,col] of [[cx-ux,cy-uy,LAB.orange],[cx+ux,cy+uy,LAB.blue]]){c.fillStyle=col;c.beginPath();c.arc(x,y,7,0,7);c.fill()}}
 if(type==='table'){const ground=x=>h*.68+Math.sin(x*.025)*8,th=.22*Math.sin(t/3.6*2*Math.PI),cx=w*.53,cy=h*.44,base=[[w*.3,h*.32],[w*.68,h*.38],[w*.76,h*.55],[w*.38,h*.51]],pts=base.map(([x,y])=>{const dx=x-cx,dy=y-cy;return[cx+dx*Math.cos(th)-dy*Math.sin(th)*.4,cy+dx*Math.sin(th)*.4+dy*Math.cos(th)]});c.strokeStyle='#46546a';c.beginPath();for(let x=0;x<w;x+=4){const y=ground(x);x?c.lineTo(x,y):c.moveTo(x,y)}c.stroke();c.fillStyle='#ff9f4330';c.strokeStyle='#ff9f43';c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill();c.stroke();const level=Math.abs(th)<.03;pts.forEach((p,i)=>{const gy=ground(p[0]),col=i===2&&!level?LAB.yellow:'#c9d2df';c.strokeStyle=col;c.beginPath();c.moveTo(...p);c.lineTo(p[0],gy);c.stroke();c.fillStyle=col;c.beginPath();c.arc(p[0],gy,4,0,7);c.fill()})}
 if(type==='note-symmetry'){const f=x=>.8*Math.cos(x)+.25*Math.sin(2*x)+.15*Math.sin(3*x),pad=14,X=x=>pad+x/Math.PI*(w-2*pad),Y=v=>h/2-v*h*.32,q=Math.min(1,(t%4)/3.2),xe=q*Math.PI;c.strokeStyle='#ffffff26';c.beginPath();c.moveTo(pad,h/2);c.lineTo(w-pad,h/2);c.stroke();c.strokeStyle=LAB.coral;c.beginPath();for(let k=0;k<=120;k++){const x=k/120*xe;k?c.lineTo(X(x),Y(f(x))):c.moveTo(X(x),Y(f(x)))}c.stroke();let z=null;for(let k=0;k<200;k++){const a=k/200*Math.PI,b=(k+1)/200*Math.PI;if(f(a)*f(b)<=0&&b<=xe){z=a;break}}if(z!=null){c.strokeStyle=LAB.acid;c.lineWidth=2;c.beginPath();c.arc(X(z),h/2,7,0,7);c.stroke();c.lineWidth=1.5}c.fillStyle=LAB.coral;c.beginPath();c.arc(X(xe),Y(f(xe)),4,0,7);c.fill();c.fillStyle='#d7e6f7';c.font='11px "JetBrains Mono",monospace';c.fillText('p',pad,h-8);c.fillText('−p',w-pad-16,h-8);c.fillText(z!=null?'ΔT = 0':'ΔT cambia de signo',z!=null?Math.min(w-70,X(z)+10):w/2-60,16)}
 if(type==='note-diverge'){const pad=14,X=x=>w/2+x*(w/2-pad)/1.6,Y=x=>h-pad-(x*x)/(1.6*1.6)*(h-2*pad-10),runs=[[.28,LAB.green],[1.12,LAB.coral]],k=Math.floor((t%4.2)/.42);c.strokeStyle='#ffffff40';c.beginPath();for(let i=0;i<=80;i++){const x=-1.6+i/80*3.2;i?c.lineTo(X(x),Y(x)):c.moveTo(X(x),Y(x))}c.stroke();runs.forEach(([a,col],j)=>{let x=j?.3:1.4;const pts=[x];for(let i=0;i<k;i++){x=x-a*2*x;pts.push(Math.max(-1.6,Math.min(1.6,x)))}c.strokeStyle=col;c.globalAlpha=.6;c.beginPath();pts.forEach((v,i)=>i?c.lineTo(X(v),Y(v)):c.moveTo(X(v),Y(v)));c.stroke();c.globalAlpha=1;const v=pts[pts.length-1];c.fillStyle=col;c.beginPath();c.arc(X(v),Y(v),5,0,7);c.fill()});c.fillStyle='#d7e6f7';c.font='11px "JetBrains Mono",monospace';c.fillText('α pequeña',pad,16);c.fillStyle=LAB.coral;c.fillText('α grande',w-pad-62,16)}
 if(type==='note-sqrt'){const pad=16,N=4000,n=Math.max(10,Math.floor(N*Math.min(1,(t%4.4)/3.6))),L=x=>Math.log10(x),X=v=>pad+(L(v)-1)/(L(N)-1)*(w-2*pad),Y=e=>h-pad-Math.min(1,e/.5)*(h-2*pad-14);let seed=29,inside=0;const rand=()=>((seed=(seed*16807)%2147483647)-1)/2147483646;c.strokeStyle=LAB.purple;c.globalAlpha=.45;c.beginPath();for(let v=10;v<=N;v*=1.1){const e=1.64/Math.sqrt(v);v===10?c.moveTo(X(v),Y(e)):c.lineTo(X(v),Y(e))}c.stroke();c.globalAlpha=1;c.fillStyle=LAB.coral;for(let i=1;i<=n;i++){const x=rand(),y=rand();inside+=(x*x+y*y<=1);if(i>=10&&(i<60||i%Math.ceil(i/60)===0))c.fillRect(X(i)-1,Y(Math.abs(4*inside/i-Math.PI))-1,2,2)}c.fillStyle='#d7e6f7';c.font='11px "JetBrains Mono",monospace';c.fillText(`n = ${n}`,pad,16);c.fillStyle=LAB.purple;c.fillText('~1/√n',w-pad-46,16)}
